#!/usr/bin/env node
/**
 * Replace sdk/js/public symlinks with real files for npm pack.
 * Skips contracts/ (generated by emit-js-contracts.mjs).
 */
import { cpSync, lstatSync, readlinkSync, readdirSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const publicRoot = join(repoRoot, "sdk/js/public");

function materializeAt(path) {
  const stat = lstatSync(path);
  if (stat.isSymbolicLink()) {
    const target = resolve(dirname(path), readlinkSync(path));
    rmSync(path, { recursive: true, force: true });
    cpSync(target, path, { recursive: true, force: true });
    return;
  }
  if (stat.isDirectory()) {
    for (const name of readdirSync(path)) {
      if (path === publicRoot && name === "contracts") continue;
      materializeAt(join(path, name));
    }
  }
}

materializeAt(publicRoot);
console.log("materialized sdk/js/public for npm pack");
